3	/**
4	 * Message attachment upload helper.
5	 *
6	 * Uploads files to the `message-attachments` Supabase Storage bucket.
7	 * Bucket must exist and have studio-member RLS policy.
8	 * Path: {studio_id}/{conversation_id}/{timestamp}-{sanitized_filename}
9	 *
10	 * Bucket creation (run once via Supabase dashboard or migration):
11	 *   INSERT INTO storage.buckets (id, name, public) VALUES ('message-attachments', 'message-attachments', false);
12	 */
13	
14	import { createClient } from '@/lib/supabase/client'
15	
16	const BUCKET = 'message-attachments'
17	const MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024 // 10 MB
18	const MAX_FILES = 5
19	const ALLOWED_TYPES = [
20	  'image/jpeg', 'image/png', 'image/gif', 'image/webp', 'image/heic',
21	  'application/pdf',
22	]
23	
24	export interface AttachmentUploadContext {
25	  studioId: string
26	  conversationId: string
27	}
28	
29	export interface UploadedAttachment {
30	  url: string
31	  filename: string
32	  mime_type: string
33	  size_bytes: number
34	}
35	
36	export type AttachmentValidationError =
37	  | { kind: 'too_many_files'; max: number }
38	  | { kind: 'file_too_large'; filename: string; maxMb: number }
39	  | { kind: 'unsupported_type'; filename: string; mime_type: string }
40	
41	export function validateFiles(files: File[]): AttachmentValidationError | null {
42	  if (files.length > MAX_FILES) {
43	    return { kind: 'too_many_files', max: MAX_FILES }
44	  }
45	  for (const file of files) {
46	    if (file.size > MAX_FILE_SIZE_BYTES) {
47	      return { kind: 'file_too_large', filename: file.name, maxMb: 10 }
48	    }
49	    if (!ALLOWED_TYPES.includes(file.type)) {
50	      return { kind: 'unsupported_type', filename: file.name, mime_type: file.type }
51	    }
52	  }
53	  return null
54	}
55	
56	export function validationErrorMessage(err: AttachmentValidationError): string {
57	  switch (err.kind) {
58	    case 'too_many_files': return `Maximum ${err.max} files per message.`
59	    case 'file_too_large': return `"${err.filename}" exceeds the 10 MB limit.`
60	    case 'unsupported_type': return `"${err.filename}" is not a supported file type.`
61	  }
62	}
63	
64	export async function uploadMessageAttachment(
65	  file: File,
66	  ctx: AttachmentUploadContext,
67	): Promise<UploadedAttachment> {
68	  const supabase = createClient()
69	
70	  // Sanitize filename: remove special chars, preserve extension
71	  const ext = file.name.split('.').pop() ?? ''
72	  const safeName = file.name
73	    .replace(/[^a-zA-Z0-9._-]/g, '-')
74	    .replace(/-+/g, '-')
75	    .toLowerCase()
76	  const uniqueName = `${Date.now()}-${safeName || `file.${ext}`}`
77	  const path = `${ctx.studioId}/${ctx.conversationId}/${uniqueName}`
78	
79	  const { error: uploadError } = await supabase.storage
80	    .from(BUCKET)
81	    .upload(path, file, {
82	      contentType: file.type,
83	      upsert: false,
84	    })
85	
86	  if (uploadError) {
87	    throw new Error(`Upload failed: ${uploadError.message}`)
88	  }
89	
90	  const { data: urlData } = supabase.storage.from(BUCKET).getPublicUrl(path)
91	
92	  return {
93	    url: urlData.publicUrl,
94	    filename: file.name,
95	    mime_type: file.type,
96	    size_bytes: file.size,
97	  }
98	}
